import{_ as e,c as p,o as r,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"13、【同人】 離下乾上","description":"周易尚氏學 - 13、【同人】 離下乾上","frontmatter":{"title":"13、【同人】 離下乾上","description":"周易尚氏學 - 13、【同人】 離下乾上"},"headers":[],"relativePath":"classics/shangshi/018.md","filePath":"classics/shangshi/018.md"}'),s={name:"classics/shangshi/018.md"};function t(h,a,l,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_13、【同人】-離下乾上" tabindex="-1">13、【同人】 離下乾上 <a class="header-anchor" href="#_13、【同人】-離下乾上" aria-label="Permalink to “13、【同人】 離下乾上”">​</a></h1><p>荀爽曰。乾舍於離。相與同居。九家曰。乾舍於離。同而為日。天日同明。故曰同人。是乾之居南。漢儒已言之矣。又荀爽注陰陽之義配日月雲。乾舍於離。配日而居。坤舍於坎。配月而居。不惟乾南。且言坤北。而惠徵君以為此漢儒言先天之鐵證也。而欲減其跡。曰荀氏用鬼易。以乾歸合離。坤歸合坎釋之。按乾歸為大有。坤歸為比。而荀氏所言者。則同人師。乃離歸坎歸也。於遊歸恆例。尚不能知。而欲減其證。其誰信之。故夫同人卦義。舍九家荀爽說。無有當者。伏坤為野。正義雲。野以喻寬廣。言和同於人。宜無遠弗屆也。易林九家荀爽皆以乾為河為海。是乾亦為大川。利涉謂五。中正有應。故傳釋為乾行。乾為君子。故利君子貞。貞卜問也。</p><p>彖曰。同人。柔得位得中而應乎乾。曰同人。同人曰。同人於野亨。利涉大川。乾行也。文明以健。中正而應。君子正也。唯君子為能通天下之志。</p><p>坤為天下。五應二故能通天下之志。詳解在焦氏易詁中。</p><p>象曰。天與火。同人。君子以類族辨物。</p><p>易以陰陽相遇為類。(王引之繁稱博引。釋類為比。豈知皆非易之所謂類。)族。正義雲。聚也。聚居一處。故曰同人。然所以能聚者。以其類也。設失類而為純陽或純陰。則不能聚矣。類族方能合異為同。乾陽物。坤陰物。同一物也。而分陰陽。辨別也。明也。同人五陽一陰。陰雖少。然五陽之所類也。即五陽之所同也。同則不分。然陰物陽物。判然不同。辨而明之。方知同之中有異。易之道。同性相違。異物相感。自類字失詁。義遂不明。</p><p>初九。同人於門。無咎。</p><p>初於二陰獨近。故曰同人於門。象曰。出門同人。亦謂二近初。初出門即遇也。虞翻以乾為門。命四變陰以應初。若卦為家人者。而惠棟姚配中皆宗之。朱漢上強命初變。以艮為門。若卦為遁者。而毛奇齡焦循宗之。是皆曲說害理。二坤爻。坤亦為門戶也。</p><h3 id="象曰。出門同人。又誰咎也。" tabindex="-1">象曰。出門同人。又誰咎也。 <a class="header-anchor" href="#象曰。出門同人。又誰咎也。" aria-label="Permalink to “象曰。出門同人。又誰咎也。”">​</a></h3><p>誰咎謂無咎。</p><p>六二。同人於宗。吝。</p><p>乾為主為宗。二五正應。故同人於宗。但卦五陽皆同於二。今二獨親五。則三四忌之。致吝之道也。下系雲遠近相取。而悔吝生。遠謂應。近謂比。遠取應則不能近取比。如無妄六二往應五而利。則不繫初。近取比。則不能遠取應。如中孚六四絕類上則不應初。而馬匹亡。是也。是故遠近萬不能兼取。同人六二遠應五。則有近不承陽之嫌。近承陽則失遠應。故吝也。彼夫鹹六二遁六二皆有應。象皆與此同。乃鹹六二曰居吉。遁六二曰執之。皆戒其動。俾遠近皆不取。不取則悔吝免也。舊說皆不知其故在三四。故鮮有得解者。</p><h3 id="象曰。同人於宗。吝道也。" tabindex="-1">象曰。同人於宗。吝道也。 <a class="header-anchor" href="#象曰。同人於宗。吝道也。" aria-label="Permalink to “象曰。同人於宗。吝道也。”">​</a></h3><p>許慎五經異義雲。易曰同人於宗吝。言同姓相取。吝道也。按此皆不明易理。不知吝之故何在。而為此穿鑿之說。同人二與五。與大有五與二同也。乃大有五應乾。無同姓之嫌。此獨曰同姓。尚能通哉。</p><p>九三。伏戎於莽。升其高陵。三歲不興。</p><p>巽為伏。為寇盜。(象失傳。詳焦氏易詁)為草莽。故曰伏戎於莽。乾為山。為陵。(象失傳。詳焦氏易詁)巽為高。乾為行。故曰升其高陵。乾為歲。離卦數三。故曰三歲。三陽遇陽。得敵。其行塞。故升高不興也。</p><h3 id="象曰。伏戎於莽。敵剛也。三歲不興。安行也。" tabindex="-1">象曰。伏戎於莽。敵剛也。三歲不興。安行也。 <a class="header-anchor" href="#象曰。伏戎於莽。敵剛也。三歲不興。安行也。" aria-label="Permalink to “象曰。伏戎於莽。敵剛也。三歲不興。安行也。”">​</a></h3><p>敵剛即陽遇陽。安行謂行難。</p><p>九四。乘其墉。弗克攻。吉。</p><p>巽為墉。四居巽上。故曰乘其墉。乘墉據高。故不能攻之。然此爻不當位。無應予。承乘皆陽。困極矣。爻辭曰吉。則不得其義。象曰困而反則。似亦不得的解。而為此無可奈何之解。獨虞翻命四變陰。當位有應。承乘皆陽。人人皆知其吉矣。然四變陰。則巽墉象毀。四居坎上。而謂乘其墉則不合矣。</p><h3 id="象曰。乘其墉。義弗克也。其吉。則困而反則也。" tabindex="-1">象曰。乘其墉。義弗克也。其吉。則困而反則也。 <a class="header-anchor" href="#象曰。乘其墉。義弗克也。其吉。則困而反則也。" aria-label="Permalink to “象曰。乘其墉。義弗克也。其吉。則困而反則也。”">​</a></h3><p>則法也。反則。言循分自守也。</p><p>九五。同人先號唃而後笑。大師克相遇。</p><p>此與屯六二義同。屯二欲上應五而為三四同性之陰所隔。故屯邅不進。然與五為正應。十年乃字。終必合也。同人九五欲應二。而為三四同性之陽所阻。故先號唃。然與二為正應。終必相遇。故後笑。伏震為笑為後。虞翻以互巽為號唃。卦伏坤。故曰師。相遇。謂遇二也。從前不能相遇者。以三四之伏戎為害也。後克而勝之。故與二相遇。</p><h3 id="象曰。同人之先。以中直也。大師相遇。言相剋也。" tabindex="-1">象曰。同人之先。以中直也。大師相遇。言相剋也。 <a class="header-anchor" href="#象曰。同人之先。以中直也。大師相遇。言相剋也。" aria-label="Permalink to “象曰。同人之先。以中直也。大師相遇。言相剋也。”">​</a></h3><p>端木國瑚曰。同人先天乾二中直。五無應。故號唃。後天離中虛。五得應。故後笑。以先後天解同人之先後。及中直之義。雖未確切。較勝於舊解。</p><p>上九。同人於郊。無悔。</p><p>居外卦之上。故曰同人於郊。乾為郊。上乘陽無應。遠居郊外。曠莫與儔。故曰志未得。伏坤為志。</p><h3 id="象曰。同人於郊。志未得也。" tabindex="-1">象曰。同人於郊。志未得也。 <a class="header-anchor" href="#象曰。同人於郊。志未得也。" aria-label="Permalink to “象曰。同人於郊。志未得也。”">​</a></h3>',29)])])}const f=e(s,[["render",t]]);export{_ as __pageData,f as default};
